// #6de0ce (d990205ec6451251316de0ce) «באג: ניגודיות וטיפוגרפיה במסכי המועמד חורגות מ-AA ומהמסגרת» — עבר QA 21.10.2026.
// Кейсы CALL-025 (контраст ≥4.5:1 каждого видимого текста, 390 и 1440), CALL-026 (заметка «שימו לב: פרטי הלקוח…»
// Figma 633:917 — белый 100 %, 15px / 24px). Эталон — ТЕКУЩИЙ Figma (решение пользователя 21.10).
// Факт 21.10 (.qa/screenshots/2026-10-21/6de0ce-*.png): минимум 5.42:1; подписи «מי על הקו» — --text-label-accent-aa
// #8c9ff1 (6.0–7.0); подсказки rgba(249,244,238,.72) — 7.07–8.77; заметка rgb(255,255,255) 15px/24px.
// Текст, затемнённый под модальным листом согласия, не меряется (решение 15.10: не дефект).
// НЕ prod-safe, @data: каждый тест создаёт кандидата «QA-AUTO-6de0ce-<stamp>» (business, link_only — без письма/SMS),
// даёт согласие и проходит тех. проверку фальшивым микрофоном; практика и официальная попытка НЕ начинаются
// (blockCallStarts обрывает candidate_start_attempt / start-voice-session). Кандидаты не удаляются (правило проекта).
// Отдельный Chrome с фальшивым микрофоном → только десктопный прогон (@desktop); 390 и 1440 — сменой окна.
import { Page } from '@playwright/test';
import { test, expect } from '../../fixtures';
import { runStamp } from '../support/api';
import { Candidate, createCandidateLink, launchCandidate, goToPractice, tap, blockCallStarts } from './support';
import { AA, Measured, measureScreen, fmt, textStyle } from './contrast-aa-support';

const HASH = '#6de0ce';
const WIDTHS = [390, 1440] as const;
const NOTE = 'שימו לב: פרטי הלקוח';

let cands: Candidate[] = [];
test.afterEach(async () => {
  for (const c of cands) await c.browser.close();
  cands = [];
});

async function resize(page: Page, w: number) {
  await page.setViewportSize({ width: w, height: w < 768 ? 844 : 900 });
}

/** Дождаться конца конечных анимаций (появление экрана/листа), бесконечные (пульс, уровень микрофона) не ждём. */
async function settle(page: Page) {
  await page.waitForFunction(
    () =>
      document.getAnimations().every((a) => {
        const it = a.effect?.getComputedTiming().iterations;
        return a.playState !== 'running' || it === Infinity;
      }),
    undefined,
    { timeout: 10_000 },
  );
}

async function newCandidate(asUser: (id: string) => Promise<Page>, kind: string) {
  const business = await asUser('business');
  const name = `QA-AUTO-6de0ce-${kind}-${runStamp()}`;
  const link = await createCandidateLink(business, name);
  test.info().annotations.push({
    type: 'test-data',
    description: `кандидат «${name}» (согласие дано, тех. проверка пройдена, практика не начата), не удаляется`,
  });
  const cand = await launchCandidate({ width: 390, height: 844 });
  cands.push(cand);
  const blocked = await blockCallStarts(cand.page);
  return { link, cand, blocked };
}

test.describe(`Экраны кандидата — контраст AA и типографика заметки (${HASH} · d990205ec6451251316de0ce)`, () => {
  test(`каждый видимый текст ≥4.5:1 к своему реальному фону на 390 и 1440: איך זה עובד, פרטי הלקוח, лист «לפני שמתחילים», тех. проверка, «פרטי לקוח לתרגול»; «מי על הקו» ≥4.5:1 @desktop @data ${HASH}`, async ({ asUser }) => {
    test.setTimeout(8 * 60_000);
    const { link, cand, blocked } = await newCandidate(asUser, 'C');
    const { page } = cand;
    const all: Measured[] = [];

    const measureAt = async (id: string, ready: () => Promise<void>) => {
      for (const w of WIDTHS) {
        await resize(page, w);
        await ready();
        await settle(page);
        const ms = await measureScreen(page, `${id} @${w}`);
        expect(ms.length, `${id} @${w}: не найдено ни одного видимого текста для замера`).toBeGreaterThan(0);
        all.push(...ms);
      }
      await resize(page, 390);
    };
    const btn = (name: string | RegExp) => async () => {
      await expect(page.getByRole('button', { name }).first()).toBeVisible({ timeout: 60_000 }); // тех. проверка микрофона — до минуты
    };

    await page.goto(link);
    // Источник: AC «כל טקסט במסכי המועמד עומד בניגודיות 4.5:1 על כל רקע שבו הוא מוצג וברוחב 390 ו-1440».
    await measureAt('ברוכים הבאים', btn('בוא נתחיל'));
    await tap(page, 'בוא נתחיל');
    await measureAt('איך זה עובד', btn('לראות פרטי לקוח'));
    await tap(page, 'לראות פרטי לקוח');
    await measureAt('פרטי הלקוח', btn('להמשיך'));
    await tap(page, 'להמשיך');
    await measureAt('лист «לפני שמתחילים»', async () => {
      await expect(page.getByText('לפני שמתחילים').first()).toBeVisible();
    });
    await page.getByRole('checkbox').first().check();
    await tap(page, /^להתחיל$/);
    await measureAt('тех. проверка — вступление', btn('להתחיל בדיקה'));
    await tap(page, 'להתחיל בדיקה');
    await measureAt('тех. проверка — «שומעים?»', btn('כן, שומעים טוב'));
    await tap(page, 'כן, שומעים טוב', 60_000);
    await measureAt('тех. проверка — готово', btn('להמשיך לתרגול'));
    await tap(page, 'להמשיך לתרגול');
    await measureAt('פרטי לקוח לתרגול', async () => {
      await expect(page.getByText('פרטי לקוח לתרגול')).toBeVisible();
      await expect(page.getByRole('button', { name: 'להתחיל תרגול' })).toBeVisible();
    });

    const min = all.reduce((a, b) => (b.ratio < a.ratio ? b : a));
    test.info().annotations.push({ type: 'contrast-min', description: `${all.length} замеров, минимум ${fmt(min)}` });

    const bad = all.filter((m) => m.ratio < AA).map(fmt);
    expect(bad, `текст ниже ${AA}:1 (факт 21.10: минимум 5.42:1)`).toEqual([]);

    // Подпись «מי על הקו» на «פרטי לקוח לתרגול» реально измерена на обеих ширинах (пример из «מה קיים»: было ~2.5:1).
    for (const w of WIDTHS) {
      const label = all.find((m) => m.label === `פרטי לקוח לתרגול @${w}` && m.text === 'מי על הקו');
      expect(label, `«מי על הקו» не измерена на «פרטי לקוח לתרגול» @${w}`).toBeTruthy();
      expect(label!.ratio, fmt(label!)).toBeGreaterThanOrEqual(AA);
    }
    // Заметка измерена (на синей/градиентной зоне).
    expect(all.some((m) => m.label.startsWith('פרטי לקוח לתרגול') && m.text.startsWith(NOTE)), `«${NOTE}…» не измерена`).toBe(true);

    expect(blocked.start + blocked.voice + cand.counts.start + cand.counts.voice, 'старт практики/официальной попытки').toBe(0);
  });

  test(`заметка «${NOTE}…» на «פרטי לקוח לתרגול» как в Figma 633:917: цвет rgb(255,255,255) без прозрачности, 15px, межстрочный 24px — на 390 и 1440 @desktop @data ${HASH}`, async ({ asUser }) => {
    test.setTimeout(4 * 60_000);
    const { link, cand, blocked } = await newCandidate(asUser, 'N');
    const { page } = cand;
    await goToPractice(page, link);

    // Источник: «מה רצוי» — «גדלי הגופן וגובה השורה באים מה-tokens ומהמסגרת»; «מה קיים» — было 84 % белого и 21px;
    // Figma 633:917 (текущая) — белый 100 %, 15/24.
    for (const w of WIDTHS) {
      await resize(page, w);
      await expect(page.getByText(NOTE).first()).toBeVisible();
      await settle(page);
      const s = await textStyle(page, NOTE);
      expect(s, `«${NOTE}…» не найдена @${w}`).not.toBeNull();
      expect.soft(s!.color, `цвет @${w}`).toBe('rgb(255, 255, 255)');
      expect.soft(s!.fill, `-webkit-text-fill-color @${w}`).toBe('rgb(255, 255, 255)');
      expect.soft(s!.opacity, `opacity предков @${w}`).toBe(1);
      expect.soft(s!.fontSize, `размер @${w}`).toBe('15px');
      expect.soft(s!.lineHeight, `межстрочный @${w}`).toBe('24px');
    }
    expect(blocked.start + blocked.voice + cand.counts.start + cand.counts.voice, 'старт практики/официальной попытки').toBe(0);
  });
});
